package com.renthub.config; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.Instant; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(ResponseStatusException.class) ResponseEntity<Map<String,Object>> status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("timestamp",Instant.now().toString(),"status",e.getStatusCode().value(),"message",e.getReason()==null?"Request failed":e.getReason()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+" "+x.getDefaultMessage()).orElse("Validation failed");return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now().toString(),"status",400,"message",m));}}
